Definition art_rg_ok (G : art_rg) : Prop :=
  (forall c, 1 <= c <= 30 -> Z.of_nat (length (cl_cache (rg_cls G c))) <= art_ic_mc c)
  /\ (forall b b', In b (rg_bl G) -> In b' (rg_bl G) -> fst b = fst b' -> b = b').

